import{z as o,x as i,o as s,c as d,q as r,j as l,D as E,d as A,s as B,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"VLAN","description":"","frontmatter":{"title":"VLAN","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vlan.md","filePath":"cs/vlan.md","lastUpdated":1791413859000}'),p={name:"cs/vlan.md"};function D(V,a,C,c,m,N){const t=i("Mermaid");return s(),d("div",null,[a[2]||(a[2]=r('<h1 id="vlan" tabindex="-1">VLAN <a class="header-anchor" href="#vlan" aria-label="Permalink to &quot;VLAN&quot;">​</a></h1><div class="epigraph"><p>在同一台交换机上把端口划进不同广播域；帧上的 VLAN 标签让中继口带着多个网段走。</p><footer>—— 据 IEEE 802.1Q；Kurose and Ross 对虚拟局域网的整理</footer></div><p><a href="/cs/csma-ca">上一课</a>对照了无线共享介质。回到交换式以太网：<a href="/cs/csma-switch">CSMA 与交换</a>默认不分割广播域，ARP 与未知单播仍会泛洪到所有端口。缺口是<strong>用标签切广播域</strong>，而不必为每个部门买一台物理交换机。本课不把生成树在 VLAN 上的实例写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>广播域过大：ARP、DHCP、未知 MAC 泛洪变成全楼噪声，也把不该互访的主机放进同一二层。物理分交换机成本高、线多。VLAN：接入端口属于某个 VID；中继口在帧头加 802.1Q 标签（VID + 优先级）。同一 VID 才二层转发。缺口是广播域的虚拟化，不是 IP 子网公式——子网常与 VLAN 一对一配置，但是后课编址才定义。</p><p><span class="marginnote">数字实例：802.1Q 的 VID 是 12 位，可用值 1 到 4094（0 与 4095 保留）——广播域的天花板就是四千出头；数据中心规模一上去就不够分，这是 VXLAN 后来把 VID 扩到 24 位（约一千六百万个）的直接动机之一。</span></p><p><span class="marginnote">Native VLAN 是中继上无标签的那一套；配置不一致会造成泄漏到错误广播域。本课只钉标签切域，不写交换机命令。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>入端口按 PVID 给未标签帧分类；出中继则插标签。交换转发键变成 (MAC, VID)，而不是裸 MAC。两个 VLAN 要通信必须上升到 IP、经路由器或三层口，即使线插在同一机箱。</p>',9)),(s(),l(n,null,{default:E(()=>[B(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACCESS%5B%22%E6%8E%A5%E5%85%A5%E5%8F%A3%3A%20%E4%B8%80%E4%B8%AA%20VID%22%5D%20--%3E%20SW%5B%22%E6%8C%89%20MAC%20%E4%B8%8E%20VID%20%E8%BD%AC%E5%8F%91%22%5D%0A%20%20TRUNK%5B%22%E4%B8%AD%E7%BB%A7%E5%8F%A3%3A%20%E6%A0%87%E7%AD%BE%E5%A4%8D%E7%94%A8%22%5D%20--%3E%20SW%0A%20%20SW%20--%3E%20ROUTER%5B%22%E8%B7%A8%20VLAN%20%E5%BF%85%E9%A1%BB%E8%B5%B0%E4%B8%89%E5%B1%82%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[A("VLAN 把「一台交换机 = 一个广播域」拆开，让"),e("a",{href:"/cs/frame-mac"},"帧与 MAC"),A(" 的泛洪范围可配。它不提供机密性：标签可被错误配置或被中继口上的主机看到；隔离是管理约定加端口信任，不是密码。端到端论证不变：切域改善的是噪声与误连，不是文件校验。")],-1)),(s(),l(n,null,{default:E(()=>[B(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20HOSTA%5B%22%E4%B8%BB%E6%9C%BA%20A%20%E5%8F%91%E6%99%AE%E9%80%9A%E5%B8%A7%22%5D%20--%3E%20ACC1%5B%22%E6%8E%A5%E5%85%A5%E5%8F%A3%E6%89%93%E4%B8%8A%20VID%2010%22%5D%0A%20%20ACC1%20--%3E%20SW%5B%22%E4%BA%A4%E6%8D%A2%E6%9C%BA%E6%8C%89%20MAC%20%E4%B8%8E%20VID%20%E6%9F%A5%E8%A1%A8%22%5D%0A%20%20SW%20--%3E%20TRK%5B%22%E4%B8%AD%E7%BB%A7%E5%8F%A3%3A%20%E5%B8%A7%E5%A4%B4%E6%8F%92%20802.1Q%20%E6%A0%87%E7%AD%BE%22%5D%0A%20%20TRK%20--%3E%20SW2%5B%22%E5%AF%B9%E7%AB%AF%E4%BA%A4%E6%8D%A2%E6%9C%BA%E8%AF%BB%E6%A0%87%E7%AD%BE%E5%88%A4%E5%9F%9F%22%5D%0A%20%20SW2%20--%3E%20ACC2%5B%22%E7%9B%AE%E6%A0%87%E6%8E%A5%E5%85%A5%E5%8F%A3%3A%20%E6%91%98%E6%8E%89%E6%A0%87%E7%AD%BE%22%5D%0A%20%20ACC2%20--%3E%20HOSTB%5B%22%E4%B8%BB%E6%9C%BA%20B%20%E6%94%B6%E5%88%B0%E6%99%AE%E9%80%9A%E5%B8%A7%22%5D%0A%20%20SW2%20--%3E%7C%22VID%20%E4%B8%8D%E5%90%8C%22%7C%20DROP%5B%22%E4%B8%8D%E5%90%91%E5%85%B6%E4%BB%96%E5%B9%BF%E6%92%AD%E5%9F%9F%E8%BD%AC%E5%8F%91%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=r('<p><span class="marginnote">直觉类比：VLAN 标签像快递单上的楼层号——同一栋楼（同一台交换机）里每层各送各的，广播互不串门；跨楼运输（中继口）时箱子外面套一层写着楼层号的袋子，到站拆袋，住户看到的仍是普通包裹。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 VXLAN 等覆盖网作为主干，不把专用 VLAN 与私有 VLAN 的全部端口角色展开。环路问题下一课生成树：VLAN 可以每 VID 一棵树，但先要有树。也不把 VLAN 当防火墙替代——安全课再谈边界。</p><p><span class="marginnote">常见误区：把 VLAN 当安全边界。标签是管理约定不是密码——配错的 Native VLAN、被信任的中继口、乃至能自己打标签的主机都能跨域；切域解决的是广播噪声与误连，机密性仍要靠加密与真正的边界设备。</span></p><p>后课默认：广播域可以小于一台交换机。冗余链路仍会把泛洪放大成环，下一课生成树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>802.1Q 用 VID 分割广播域；跨域要三层。</li><li>转发键是 MAC 加 VLAN，不是只学 MAC。</li><li>环路仍在，下一课生成树。</li><li>出处：IEEE 802.1Q；Kurose and Ross。</li></ul>',7))])}const _=o(p,[["render",D]]);export{f as __pageData,_ as default};
